@sealed
class LibraryTransportImpl extends RustOpaque implements LibraryTransport {
  // Not to be used by end users
  LibraryTransportImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  LibraryTransportImpl.frbInternalSseDecode(
    BigInt ptr,
    int externalSizeOnNative,
  ) : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_LibraryTransport,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_LibraryTransport,
    rustArcDecrementStrongCountPtr: RustLib
        .instance
        .api
        .rust_arc_decrement_strong_count_LibraryTransportPtr,
  );

  /// Add a folder as a collection and sync its tracks.
  Future<AddFolderCollectionResult> addFolderCollection({
    required String folderPath,
    required bool scanFolderTree,
    String? name,
  }) => RustLib.instance.api.crateApiLibraryLibraryTransportAddFolderCollection(
    that: this,
    folderPath: folderPath,
    scanFolderTree: scanFolderTree,
    name: name,
  );

  /// Create an empty playlist collection.
  Future<LibraryCollectionSummary> addPlaylistCollection({
    required String name,
    required bool sortable,
  }) =>
      RustLib.instance.api.crateApiLibraryLibraryTransportAddPlaylistCollection(
        that: this,
        name: name,
        sortable: sortable,
      );

  /// Bulk analysis for a collection, fanned out onto the library cmd bus.
  ///
  /// Resolves the target set server-side with the non-force skip rule (tracks
  /// that already carry BPM/key or have an analysis row are skipped), then
  /// publishes one [`Event::AnalyzeTrack`] per target — the same bus path as
  /// single-track analyze, so per-track `TrackProgress` / `TrackAnalyzed`
  /// events flow unchanged. With `generate_stems`, an
  /// [`Event::GenerateStems`] is queued for every file track (stem cache
  /// state is independent of BPM/tags; the serial stem queue no-ops on valid
  /// caches, including native `.stem.mp4` files). Returns the queued analysis
  /// ids so the UI can mark them analyzing up front.
  Future<AnalyzeCollectionResult> analyzeCollection({
    required String collectionId,
    required bool force,
    required bool generateStems,
  }) => RustLib.instance.api.crateApiLibraryLibraryTransportAnalyzeCollection(
    that: this,
    collectionId: collectionId,
    force: force,
    generateStems: generateStems,
  );

  /// Queue analyze for a track via the library cmd bus only (worker emits evt).
  Future<void> analyzeTrack({required String trackId, required bool force}) =>
      RustLib.instance.api.crateApiLibraryLibraryTransportAnalyzeTrack(
        that: this,
        trackId: trackId,
        force: force,
      );

  /// Apply performance history settings from app settings.
  Future<void> applyHistorySettings({
    required bool enabled,
    required int sessionIdleMinutes,
    required int minPlaySeconds,
    required double minDeckVolume,
  }) =>
      RustLib.instance.api.crateApiLibraryLibraryTransportApplyHistorySettings(
        that: this,
        enabled: enabled,
        sessionIdleMinutes: sessionIdleMinutes,
        minPlaySeconds: minPlaySeconds,
        minDeckVolume: minDeckVolume,
      );

  /// Apply library analysis duration, stem format/model, and tag write-back.
  Future<void> applyLibrarySettings({
    required LibraryAnalysisDurationSetting analysisDuration,
    required String stemsFormat,
    required String stemsModel,
    required bool tagWriteBack,
  }) =>
      RustLib.instance.api.crateApiLibraryLibraryTransportApplyLibrarySettings(
        that: this,
        analysisDuration: analysisDuration,
        stemsFormat: stemsFormat,
        stemsModel: stemsModel,
        tagWriteBack: tagWriteBack,
      );

  /// Wipe the Mixar-owned ONNX model cache directory.
  Future<void> clearModelCache() => RustLib.instance.api
      .crateApiLibraryLibraryTransportClearModelCache(that: this);

  /// Delete all track stem rows and wipe the stems cache directory.
  Future<void> clearStemCache() => RustLib.instance.api
      .crateApiLibraryLibraryTransportClearStemCache(that: this);

  /// Delete cached waveform overview rows (regenerated on next fetch).
  Future<void> clearWaveformCache() => RustLib.instance.api
      .crateApiLibraryLibraryTransportClearWaveformCache(that: this);

  /// Create a sampler bank and return the stored row.
  Future<SamplerBankInfo> createSamplerBank({
    required String name,
    SamplerPlayMode? playMode,
  }) => RustLib.instance.api.crateApiLibraryLibraryTransportCreateSamplerBank(
    that: this,
    name: name,
    playMode: playMode,
  );

  /// Delete a collection (folder or playlist). Member tracks that no other
  /// collection references are removed from the pool.
  Future<void> deleteCollection({required String collectionId}) =>
      RustLib.instance.api.crateApiLibraryLibraryTransportDeleteCollection(
        that: this,
        collectionId: collectionId,
      );

  Future<void> deleteHistorySession({required String sessionId}) =>
      RustLib.instance.api.crateApiLibraryLibraryTransportDeleteHistorySession(
        that: this,
        sessionId: sessionId,
      );

  /// Delete a saved loop slot (worker emits `LoopsChanged`).
  Future<void> deleteLoop({required String trackId, required int slot}) =>
      RustLib.instance.api.crateApiLibraryLibraryTransportDeleteLoop(
        that: this,
        trackId: trackId,
        slot: slot,
      );

  /// Export the selected playlists (and folder collections) into `destination`
  /// in the Pioneer CDJ/XDJ USB layout. `destination` is a mounted USB drive or
  /// a folder; it is created when missing.
  Future<CdjExportReport> exportCdjUsb({
    required String destination,
    required List<String> playlists,
    required List<String> folders,
    required bool refreshFiles,
  }) => RustLib.instance.api.crateApiLibraryLibraryTransportExportCdjUsb(
    that: this,
    destination: destination,
    playlists: playlists,
    folders: folders,
    refreshFiles: refreshFiles,
  );

  Future<void> exportHistorySession({
    required String sessionId,
    required HistoryExportFormatSetting format,
    required String destPath,
  }) =>
      RustLib.instance.api.crateApiLibraryLibraryTransportExportHistorySession(
        that: this,
        sessionId: sessionId,
        format: format,
        destPath: destPath,
      );

  /// Queue stem generation for a track via the library cmd bus only.
  ///
  /// Separate from [`Self::analyze_track`]: analysis never generates stems
  /// implicitly. No-op server-side when a valid stem cache already exists.
  Future<void> generateStems({required String trackId}) =>
      RustLib.instance.api.crateApiLibraryLibraryTransportGenerateStems(
        that: this,
        trackId: trackId,
      );

  /// Analyzed beat grid, if present.
  Future<BeatGridData?> getBeatGrid({required String trackId}) => RustLib
      .instance
      .api
      .crateApiLibraryLibraryTransportGetBeatGrid(that: this, trackId: trackId);

  /// Load one track including embedded artwork when present.
  Future<LibraryTrackSummary?> getTrack({required String trackId}) => RustLib
      .instance
      .api
      .crateApiLibraryLibraryTransportGetTrack(that: this, trackId: trackId);

  /// L0 overview peaks from the library DB (generates overview when missing).
  Future<WaveformPeaks?> getWaveformOverview({required String trackId}) =>
      RustLib.instance.api.crateApiLibraryLibraryTransportGetWaveformOverview(
        that: this,
        trackId: trackId,
      );

  /// L1 JIT window peaks from the decode cache (decodes the file if needed).
  Future<WaveformPeaks> getWaveformWindow({
    required String trackId,
    required int startMs,
    required int endMs,
    required int buckets,
  }) => RustLib.instance.api.crateApiLibraryLibraryTransportGetWaveformWindow(
    that: this,
    trackId: trackId,
    startMs: startMs,
    endMs: endMs,
    buckets: buckets,
  );

  Future<bool> historyCanResume() => RustLib.instance.api
      .crateApiLibraryLibraryTransportHistoryCanResume(that: this);

  Future<void> historyDeclineRestore() => RustLib.instance.api
      .crateApiLibraryLibraryTransportHistoryDeclineRestore(that: this);

  Future<String> historyDir() => RustLib.instance.api
      .crateApiLibraryLibraryTransportHistoryDir(that: this);

  Future<void> historyNewSession() => RustLib.instance.api
      .crateApiLibraryLibraryTransportHistoryNewSession(that: this);

  /// Restore prompt when the last session is still inside the idle window.
  Future<HistoryRestorePromptInfo?> historyRestorePrompt() => RustLib
      .instance
      .api
      .crateApiLibraryLibraryTransportHistoryRestorePrompt(that: this);

  Future<void> historyRestoreSession({required String sessionId}) =>
      RustLib.instance.api.crateApiLibraryLibraryTransportHistoryRestoreSession(
        that: this,
        sessionId: sessionId,
      );

  Future<void> historyResumeSession() => RustLib.instance.api
      .crateApiLibraryLibraryTransportHistoryResumeSession(that: this);

  Future<List<HistoryEntryInfo>> historySessionEntries({
    required String sessionId,
  }) =>
      RustLib.instance.api.crateApiLibraryLibraryTransportHistorySessionEntries(
        that: this,
        sessionId: sessionId,
      );

  /// Import a Mixxx library at `db_path` into this transport's manager.
  ///
  /// Reads the Mixxx database outside the manager lock, then migrates into the
